TAB_Biography = TAB_Biography or {}
TAB_Biography[-1] = {"s_Biography","s_Describe1","s_Describe2","s_Describe3","u_Reward"}
TAB_Biography[11202] = {"Do bị nhiễm virus, sau khi tỉnh dậy ở nhà xác hắn không biết trước đây đã làm gì, song vừa đột biến thì có được khả năng phi thường. Khi gặp kẻ địch có thể hút ký ức, năng lực của họ, thậm chí có thể biến hình giống họ. Khi số lượng kẻ địch và người đi đường bị tiêu diệt tăng, năng lực của hắn cũng  mạnh hơn","Nam","Chưa rõ","Mỹ",{{8002,20}}}
TAB_Biography[11407] = {"Một loại robot thông minh chiến đấu đa năng thuộc quân đoàn bộ binh cơ giới 'YoRHa', thành viên YoRHa bỏ tên và chỉ gọi nhau bằng mã số, dù họ bị cấm thể hiện cảm xúc, nhưng mỗi thành viên đều có cá tính riêng biệt","Nữ","Chưa rõ","Thành trì mặt trăng",{{8002,40}}}
TAB_Biography[11512] = {"Thiếu nữ xinh đẹp trầm mặc ít nói, ít thể hiện tình cảm. Sở hữu dòng máu Nhật Bản và Mikasa. Cô có cơ bụng tám múi, năng lực thể chất và kỹ thuật chiến đấu tuyệt vời, năng lực tương đương với 100 binh lính. Cô là sinh viên tốt nghiệp cấp cao của binh đoàn huấn luyện kỳ 104, được đánh giá là tài năng trước giờ chưa từng có","Nữ","Đao Săn","Shiganshina",{{8002,50}}}
TAB_Biography[11513] = {"Binh trưởng, đội trưởng đội tác chiến đặc biệt của quân đoàn điều tra. Tính khí thô lỗ, nhưng thực ra lại là một người bên ngoài lạnh lùng bên trong ấm áp, tinh tế, sống tình cảm và rất quan tâm đến đồng đội của mình","Nam","Đao Địa Ngục","Eldia",{{8002,50}}}
TAB_Biography[11514] = {"Khi còn là học sinh vì cơ thể ốm yếu nên đã nghi ngờ về tương lai của bản thân. Sau khi bước vào xã hội, đã rơi vào tình trạng suy sụp vì thất nghiệp, tìm về với niềm vui trở thành anh hùng lúc nhỏ nên bắt đầu rèn luyện thân thể, và trong quá trình rèn luyện đó đã đánh bại đủ loại quái nhân","Nam","Găng Tay Cự Nhân","Thành phố Z",{{8002,50}}}
TAB_Biography[12515] = {"Angemon có đôi cánh tỏa sáng, trên người mang một chiếc áo trắng tinh thiêng liêng. Là sự tồn tại hoàn toàn lương thiện, được gọi là Digimon mang lại hạnh phúc, đối xử với bọn tà ác rất lạnh lùng, không ngừng tấn công cho đến khi đối thủ bị tiêu diệt hoàn toàn. Kỹ năng tất sát là dùng nắm đấm ánh sáng lấp lánh để tấn công {Thiên Đường Quyền} của đối thủ","Nam","Gậy Thiên Thần","Digital World",{{8002,50}}}
TAB_Biography[12516] = {"Angewomon với tạo hình mỹ nữ. Cô có tính cách dịu dàng, nhưng tuyệt đối không nhượng bộ bất công và xấu xa, không bao giờ nương tay nếu đối thủ không ăn năn hối cải. Kỹ năng tất sát là {Mũi Tên Thần Thánh} phát ra tia sét đánh cực mạnh.","Nữ","Mũi Tên Thiên Thần","Digital World",{{8002,50}}}
TAB_Biography[13101] = {"Thân thể cường tráng, cao 15 mét, toàn thân được bao bọc bởi áo giáp siêu cứng, ngay cả kiếm của quân đoàn điều tra cũng bị làm gãy, công nghệ Continental có thể khắc chế được áo giáp này. Tấn công và phòng thủ đều rất xuất sắc, nhưng không linh hoạt","Nam","Chưa rõ","Marley",{{8002,10}}}
TAB_Biography[13303] = {"Trước đây từng là một tên cướp biển tàn bạo và đáng sợ, tiền thưởng truy nã ông lên tới 296.000.000 Vàng. Sau này trở thành quân cách mạng. Trước 'sự kiện trọng đại' ông tự nguyện để Tiến sĩ Vegapunk thay đổi và làm mất đi ý thức hoàn toàn. Ông đã ăn trái Nikyu Nikyu no Mi và biến thành 'người chân thú' có thể đẩy được mọi thứ bao gồm cả mệt mỏi và đau khổ, thậm chí còn có thể đẩy cả không khí","Nam","Chưa rõ","Sorbet",{{8002,30}}}
TAB_Biography[13405] = {"Ông là quân nhân thuộc 'Cơ quan thứ 7' và có tên gọi khác là 'Quỷ Đỏ'. Trong cuộc nội chiến của trận Ma Đạo 2, ông đã bị thương và lâm nguy, sau khi được Kukunoe phẫu thuật cải tạo thì đã trở thành người máy, sau này hoạt động dựa trên thân phận trợ lý của Kukunoe. Có được khả năng điều khiển lực từ trong quá trình cải tạo. Điều trái ngược với vẻ ngoài chính là bình thường thì ăn nói rất tri thức nhưng đối diện với phụ nữ hoặc trẻ em thì lại rất 'đàn ông'","Nam","Chưa rõ","Vùng Đất Thần Bí",{{8002,40}}}
TAB_Biography[13509] = {"Cô gái xinh đẹp với đặc trưng là mái tóc ahoge và đôi mắt đen. Vũ khí của cô là chiếc khiên lớn. Có tính cách hiếu kỳ nên đã chấp nhận lời mời của cô bạn và bắt đầu chơi game 'New World Online', vì sợ đau nên đã xây dựng nhân vật với lực phòng thủ đạt tối đa. Trưởng Guild của Guild Maple","Nữ","Bóng Ngược Đêm Tối","Quận Neon",{{8002,50}}}
TAB_Biography[14404] = {"Zenyatta là một vị sư omnic lang thang khắp thế gian để khai sáng thế giới tâm linh của bản thân. Tương truyền ai may mắn gặp được Zenyatta thì cuộc đời của họ sẽ được thay đổi","Nam","Chưa rõ","Shambali",{{8002,40}}}
TAB_Biography[14406] = {"Cô gái lạnh lùng vô tình, toàn thân được bao bọc bởi máy móc, chỉ có thể trả lời đơn giản với các mệnh lệnh nhưng lại có phản ứng với Ragnar","Nữ","Chưa rõ","Cơ Quan Thứ 7",{{8002,40}}}
TAB_Biography[14510] = {"Miku đáng yêu nhất thế giới, những bài hát đã phát hành đều được biết đến rộng rãi vì rất hay, cô mặc nhiều bộ trang phục khác nhau do sở thích cá nhân, những hình ảnh trang phục này đã khiến người yêu mến cô đặt cho rất nhiều biệt danh","Nữ","Microphone","Bắc Hải",{{8002,50}}}
TAB_Biography[14511] = {"Cô là người lái Eva 00, người đủ tiêu chuẩn đầu tiên để lái Eva 00. Bắt đầu với kế hoạch Eva 00, cô dành toàn bộ thời niên thiếu của mình vào phòng nghiên cứu, sau khi trưởng thành thì đã phát triển và khởi động dòng Eva 00, cô đã bay thử và cung cấp dữ liệu từ việc thử nghiệm và là người theo chủ nghĩa thuần chay","Nữ","Liềm","NERV",{{8002,50}}}
TAB_Biography[21202] = {"Cựu đội trưởng đội 2 của Gotei 13, cựu tổng tư lệnh của Ẩn mật cơ động, cựu quân đoàn trưởng của quân đoàn 1, cũng là người đứng đầu đời thứ 22 Shihouin Yoruichi của 4 gia tộc lớn ở Thế Giới Linh Hồn, giỏi chiến đấu bằng tay và thuấn bộ, có biệt danh là 'Tốc Thánh', là bạn thân của Urahara Kisuke cựu đội trưởng đội 12","Nữ","Chưa rõ","Thế Giới Linh Hồn",{{8002,20}}}
TAB_Biography[21512] = {"Là một đứa con lai, bên trong cơ thể sở hữu nhiều loại sức mạnh cùng lúc. Khi gia đình bị quái vật tấn công, để cứu gia đình cậu đã nhận lấy sức mạnh Shinigami và từ đó cậu bắt đầu việc ở Shinigami","Nam","Trảm Nguyệt","Trấn Karakura",{{8002,50}}}
TAB_Biography[22101] = {"Là một Âm Dương Sư thiên tài, sau khi chị gái Hikari bị thương cô đã đi khắp thế giới tìm Cổng Địa Ngục quyết đấu để trả thù cho chị gái","Nữ","Minh Âm","Chân núi",{{8002,10}}}
TAB_Biography[22304] = {"Bố hiện tại là lưỡi hái tử thần chính, mẹ là thợ đúc liềm. Nhưng mối quan hệ giữa Maka Albarn và người bố có tính cách suồng sã rất tồi tệ, để làm ra vũ khí mạnh hơn chiếc liềm của bố, cô đã vào học tại Shibusen. Thành tích ưu tú, rất chăm chỉ, ghét thừa nhận thất bại, điều mạnh mẽ nhất là sở hữu lòng dũng cảm chống lại nỗi sợ hãi","Nữ","Chưa rõ","Quận Neon",{{8002,30}}}
TAB_Biography[22404] = {"Là hậu duệ của thủ lĩnh Mafia đầu tiên sau khi di cư đến Nhật Bản, được gia tộc chọn làm người kế vị thứ 10, nhưng lại quyết liệt từ chối. Sau khi nhận được viên đạn Dying Will, đã phát huy những khả năng tiềm tàng đáng kinh ngạc. Vốn dĩ yếu đuối, muốn trốn tránh mọi thứ nhưng lại rất coi trọng tình bạn, khi bạn gặp nạn đã bất chấp mọi thứ để chiến đấu","Nam","Chưa rõ","Can Thành Đinh",{{8002,40}}}
TAB_Biography[22407] = {"Zoldyck Killua xuất thân từ gia tộc sát thủ Zoldyck ở núi Kukupushan với độ cao hơn 3000 mét nằm ở Cộng Hòa Padokia, được đào tạo nghiêm ngặt để trở thành sát thủ khủng bố lạnh lùng từ năm 3 tuổi. Với tư chất tốt nhất trong gia tộc nên được kỳ vọng tương lai sẽ trở thành chủ nhân, nhưng cậu không muốn đi theo con đường đã được sắp đặt sẵn nên đã bỏ nhà đi và bắt đầu hành trình thám hiểm","Nam","Chưa rõ","Padokia",{{8002,40}}}
TAB_Biography[22513] = {"Chàng trai tốt bụng và ấm áp, để chữa trị cho em gái bị biến thành quỷ, không ngừng tìm kiếm kẻ thù trong khi chiến đấu với quỷ dữ. Là người tốt bụng, quyết đoán, dũng cảm, bình tĩnh, thông minh tìm ra được điểm mấu chốt để phá vỡ tình huống trong lúc hiểm nguy. Có trách nhiệm tận tâm với mọi chuyện, đối tốt với mọi người, luôn lo lắng và nỗ lực chăm sóc cho người khác","Nam","Nhật Luân Kiếm","Núi Kumotori",{{8002,50}}}
TAB_Biography[22514] = {"Là một pháp sư loài người sống trong khu rừng Phép Thuật cách xa ngôi làng của con người, sử dụng được phép thuật, chiến đấu với quái vật giống như đang cạnh tranh với người khác vậy. Đang kinh doanh ở ngôi nhà vạn vật 'Tiệm Marisa'","Nữ","Lò Bát Quái Nhỏ","Vùng Đất Ảo Giác",{{8002,50}}}
TAB_Biography[23405] = {"Thiên tài nhận được tôn hiệu nhà luyện kim trẻ tuổi nhất trong lịch sử. Nguồn gốc của tên gọi khác 'Nhà luyện kim bằng thép' không chỉ vì sở hữu tay và chân bằng máy móc mà còn vì cậu có một trái tim sắt thép. Ngoại hình ưa nhìn, có mái tóc dài và đôi mắt màu vàng, có quyết tâm và ý chí kiên cường","Nam","Chưa rõ","Thế Giới Luyện Kim",{{8002,40}}}
TAB_Biography[22515] = {"Từ nhỏ đã ở 'Thiên Đạo Cung', theo Carmel và Merihim tập luyện chăm chỉ để trở thành chiến binh hoàn hảo, sát thủ văn võ song toàn. Đã thi triển toàn bộ sức mạnh của 'Ngọn Lửa Thiên Đường' và trở thành 'Sát thủ có đôi mắt rực lửa'. Học được các phép tự tại như 'chân hồng', 'phi diệm', 'phán xét', 'kết tội'...","Nữ","Kiếm Thiên Kiếp","Thiên Đạo Cung",{{8002,50}}}
TAB_Biography[23508] = {"Một ma đạo sĩ cấp S mạnh mẽ và xinh đẹp. Ngoài hội trưởng ra thì cô là ma đạo sĩ được lòng người nhất trong hội. Tham gia 'giải ma đạo sĩ cấp S' và trở thành thành viên trẻ tuổi của hội vượt qua cuộc thi. Chiêu tuyệt vời nhất của cô là thu thập vũ khí, giáp trong một không gian phép thuật, và triệu hồi ra để thay đổi trang phục, bình thường cũng có thể đổi nhiều bộ trang phục khác nhau","Nữ","Cherry Đao Yêu","Edoras",{{8002,50}}}
TAB_Biography[23509] = {"Một trong những người thừa kế tinh thần hoàng kim, bên ngoài lạnh lùng bên trong ấm áp, tính cách kiên định, lý trí và nguyên tắc. Thường bị hiểu lầm là người tàn nhẫn và lạnh nhạt","Nam","Sứ Giả Thế Thân","Quận Neon",{{8002,50}}}
TAB_Biography[24406] = {"Giỏi sử dụng phép thuật đen, tính cách ngang ngược, nóng nảy. Là người tỉ mỉ, trong chiến đấu sẽ đưa ra phán đoán chính xác về tình hình, rất coi trọng đồng đội, có tinh thần hy sinh vào những thời điểm quan trọng. Mỗi khi Lina Inverse tức giận cô sẽ dùng Dragon Slave để trút giận. Ghét người khác nói về bộ ngực lép của mình","Nữ","Chưa rõ","Sephiria",{{8002,40}}}
TAB_Biography[24510] = {"Cô bé mơ về những cô nàng phép thuật, nhưng cũng khao khát một cuộc sống bình thường. Lúc nhỏ bị mẹ phong ấn ma lực, ký ức và tri thức nên đã trở thành một cô gái bình thường. Sau này có được 'Bảo thạch ma pháp đỏ' nên có thể trở thành cô gái ma pháp Illya","Nữ","Bảo Thạch Ma Pháp Đỏ","Fuyuki",{{8002,50}}}
TAB_Biography[24511] = {"Trong hai cô hầu gái song sinh đảm đương mọi công việc trong dinh thự Roswaal, cô chính là em gái Rem, lúc nhỏ người thân bị phù thủy sát hại, sừng của chị cô bị chặt đứt nên từ đó cô rất hận phù thủy. Miệng lưỡi độc địa và thờ ơ nhưng thực ra tâm hồn rất mạnh mẽ và dịu dàng","Nữ","Búa Sao Băng","Lugnica",{{8002,50}}}
TAB_Biography[31101] = {"Từng là võ sư số một thế giới, được thế giới tôn là 'Thần võ'. Người sáng lập môn phái võ học Trường Rùa, cha đẻ của Kamehameha, đệ tử ưu tú nhất của Master Mutaito","Nam","Chưa rõ","Quận Neon",{{8002,10}}}
TAB_Biography[31406] = {"Giỏi tấn công kẻ địch về mặt tinh thần. Chàng trai mang đầy hận thù, tự xưng là 'Kẻ từ bỏ mọi thứ'. Tính cách lạnh lùng, vô tình, nhưng bên trong lại là người đầy nhiệt huyết, rất yêu thương và quan tâm đến em trai. Lúc bạn bè nguy nan nhất thì anh luôn chạy đến giúp đỡ","Nam","Chưa rõ","Quận Neon",{{8002,40}}}
TAB_Biography[31511] = {"Người thừa kế quyền pháp mạnh nhất có bảy vết sẹo hình chòm sao Bắc Đẩu trên ngực, nỗ lực hết mình để quét sạch cái ác và sự bất công, đồng thời không ngừng truy tìm người yêu Yulia. Là một người đàn ông mạnh mẽ nhưng không tự cao, kiên trì và tốt bụng, ấm áp nhưng không bộc lộ ra ngoài","Nam","Côn Nhị Khúc","Nước Shura",{{8002,50}}}
TAB_Biography[31512] = {"Black có dáng người thon thả, làn da trắng, trên đầu có hai bím tóc, mặc chiếc áo khoác màu đen. Đôi lúc mắt trái sẽ phát ra ngọn lửa màu xanh. Vũ khí sử dụng là khẩu súng Black Rock Cannon mỗi giây bắn được 20 viên nham thạch và có thể biến thành khẩu súng máy siêu to.","Nữ","Black Rock Cannon","Thế Giới Trắng Tinh",{{8002,50}}}
TAB_Biography[31513] = {"Xuất thân từ tộc Sparta ở Hy Lạp, giữ quân hàm chỉ huy, có biệt danh là 'Linh hồn Sparta'. Vì chống lại Zeus nên Aces đã bày mưu để Kratos tự tay sát hại vợ và con gái ruột, sau này Kratos đã hóa thân thành kẻ phục thù và tiêu diệt Aces, trở thành Thần Chiến Tranh mới. Sau đó, vì chống lại người cha ruột Zeus nên Kratos bị cách chức, vì thế cậu quyết định phục thù Zeus","Nam","Đao Hỗn Loạn","Sparta",{{8002,50}}}
TAB_Biography[31514] = {"Con cả của gia đình Yuuki, từ nhỏ đã được giáo dục theo kiểu tinh anh, được sắp đặt sẵn cuộc đời thành công, làm theo mong muốn của bố mẹ một cách máy móc. Sau khi gia nhập SAO thì trở thành tù nhân của thế giới ảo, để trở về quỹ đạo cuộc sống ban đầu Asuna không chịu thua và điên cuồng diệt quái và luyện cấp, trở thành phó chủ huy của Huyết Minh Kỵ Sĩ Đoàn","Nữ","Ánh Sáng Lấp Lánh","Setagaya",{{8002,50}}}
TAB_Biography[32202] = {"Lãnh chúa trẻ tuổi của Nam Cung Thành, là người chính nghĩa và có tinh thần chiến đấu, kỹ năng điêu luyện, {Vòng Tay Lục Châu} trên cổ tay trái khiến cậu sở hữu sức mạnh vô hạn","Nam","Chưa rõ","Thành Nam Cung",{{8002,20}}}
TAB_Biography[32404] = {"Đứa trẻ mồ côi của băng hải tặc, sau khi lớn lên vì hận bố nên đã đổi theo họ mẹ. Là đội trưởng đội 2 của băng hải tặc Râu Trắng, thực lực rất mạnh","Nam","Chưa rõ","Baderila",{{8002,40}}}
TAB_Biography[32407] = {"Trưởng nữ của tông gia Hyuga nổi tiếng, sở hữu đôi mắt trắng Byakugan vô cùng thuần khiết, được Toneri Otsutsuki và Hamura Otsutsuki tôn là 'Công chúa Byakugan'","Nữ","Chưa rõ","Làng Lá",{{8002,40}}}
TAB_Biography[32515] = {"Thành viên của Ám Bộ, đội trưởng đội 7, thầy giáo của nhiều gennin. Năm 12 tuổi đã trở thành thiên tài nhẫn giả Jounin, mắt trái được cấy ghép bằng con mắt đặc biệt, nó có thể sao chép rất nhiều nhẫn thuật, tên tuổi vang danh khắp các nước","Nam","Đao Bạch Nha","Làng Lá",{{8002,50}}}
TAB_Biography[32516] = {"Sinh ra ở vương quốc Băng, bị ruồng bỏ, để sống sót cậu không ngừng cướp bóc và sát hại. Để tìm kiếm em gái và viên ngọc Hiruiseki, cậu đã nhờ bác sĩ phẫu thuật ở ma giới cấy ghép Tà Nhãn","Nam","Kiếm Giáng Ma","Vương quốc Băng",{{8002,50}}}
TAB_Biography[33303] = {"Là một tên cướp biển nhưng lại có mối quan hệ với những nhà lãnh đạo hàng đầu của chính phủ thế giới, là chàng trai bí ẩn. Từng tập sự trong băng hải tặc One Piece, sau khi băng hải tặc đó tan rã thì thành lập băng hải tặc Tóc Đỏ, là một trong Tứ Hoàng ở New World, tiền truy nã là 4.048.900.000 Vàng","Nam","Chưa rõ","Tây Hải",{{8002,30}}}
TAB_Biography[33405] = {"Con trai của thợ săn quái vật mạnh nhất vũ trụ 'Umibouzu'. Là người hiếu thắng, một khi bắt đầu chiến đấu thì không thể dừng. Máu lạnh, không màng tới gia đình, thầy trò, thuộc hạ, bạn bè..., không do dự khi ra tay với bố và thầy. Luôn nở nụ cười trên môi, không quan tâm kẻ yếu, phấn khích khi gặp kẻ mạnh, cố gắng khiêu chiến với kẻ mạnh cho dù họ là ai","Nam","Chưa rõ","Tộc Dạ Thổ",{{8002,40}}}
TAB_Biography[33508] = {"Ông si mê nghệ thuật chiến đấu tàn bạo Ám Sát Quyền, bị thôi thúc bởi mong muốn tàn sát, Akuma đã diệt thầy hại đệ; các đồ đệ tận mắt chứng kiến sư phụ bị sát hại nên đã thề sẽ báo thù. Sau khi sát hại sư huynh, Akuma tiếp tục tìm kiếm các chiến binh mạnh nhất trên thế giới để chiến đấu nhằm thách thức giới hạn của bản thân","Nam","Ngọc Đạt Ma","Quận Neon",{{8002,50}}}
TAB_Biography[34509] = {"Một trong 'Tam Nhẫn' huyền thoại, người quan trọng nhất đối với bà chính là người yêu và em trai. Giỏi thể thuật và y thuật. Trong đại chiến nhẫn giả lần 4, bà đảm nhiệm chức tổng tham mưu liên quân nhẫn giả, đóng góp vai trò quan trọng","Nữ","Phù Hiệu Sức Mạnh","Làng Lá",{{8002,50}}}
TAB_Biography[41301] = {"Thai nghén từ Tiên Thạch, dẫn dắt bầy khỉ vào Thủy Liêm Động nên trở thành chúng hầu vương, tôn là 'Mỹ Hầu Vương'. Sau bái Bồ Đề tổ sư học nghệ","Nữ","Chưa rõ","Đông Thắng Thần Châu",{{8002,30}}}
TAB_Biography[41403] = {"Người đấu kiếm La Mã cổ đại. Tin tuyệt đối vào sự nhẫn nại. Không phụ nguyện vọng Chén Thánh gửi gắm, có chăng chỉ là ý nguyện ra chiến trường. Vì với Berserker mà nói chiến trường là nơi chỉ có kẻ mạnh yếu, đầy đau khổ và thí luyện","Nam","Chưa rõ","La Mã cổ đại",{{8002,40}}}
TAB_Biography[42402] = {"Loại alpha, tự xưng là 'Thiên sứ vui chơi', thực ra là 'Thiên sứ chiến lược', Synapse gọi người đó là 'Icarus'","Nữ","Chưa rõ","Synapse",{{8002,40}}}
TAB_Biography[42502] = {"Thân phận thật sự là quốc vương thứ 5 Uruk vương triều Early Sumerian khu vực Mesopotamia, nhân vật sử thi cổ xưa nhất, 'Vua Anh Hùng' của nhân loại. Ngài có '2 phần là thần, 1 phần là người', tính cách cao ngạo, từng tự cho mình là bạo chúa vô địch","Nam","Kho Báu Đế Vương","Mesopotamia",{{8002,50}}}
TAB_Biography[42509] = {"Xem loài người là món ăn, hơn một vạn người bị cô ta sát hại, có thể nói là Tinh Linh gian ác nhất. Hơn nữa cô ta có thể kéo con người vào trong cái bóng của mình, nuốt chửng không dấu vết.","Nữ","Súng Kíp","Lân Giới",{{8002,50}}}
TAB_Biography[42510] = {"Xếp hạng ba trong bảy người siêu năng lực ở Thâm Mộc Thành, 'Người năng lực hệ Điện' mạnh nhất thành này, biệt hiệu 'RailGun'. Hiếu thắng, chuộng chính nghĩa, cởi mở nhưng không nhẫn nại, không thẳng thắn.","Nữ","Tiền Game","Thâm Mộc Thành",{{8002,50}}}
TAB_Biography[43501] = {"Nữ võ sĩ khoác giáp chiến, là nữ nhi đại thần, do thần Odin tạo ra. Họ bay lượn trong nhiều chiến trường, đủ tư cách từ các anh hùng tử chiến, linh hồn họ sẽ mang đến cung điện Vàng rực rỡ - Valhalla","Nữ","Kiếm Long Nha","Thiên Đường",{{8002,50}}}
TAB_Biography[43503] = {"Rút Kiếm Thạch Trung ra, ma lực kiếm khiến cô ấy ngừng phát triển. Lúc trở thành vua Saber thì vứt bỏ thân phận 'người', không suy nghĩ cho bản thân nữa, chỉ lo quốc gia và nhân dân. Sau khi cầm Kiếm Thạch Trung duy trì dung mạo cô gái khiến thần dân sợ sệt và không tín nhiệm. Xưng vương xong rong ruổi sa trường như đấng nam nhi.","Nữ","Kiếm Thạch Trung","Nước Anh cổ đại",{{8002,50}}}
TAB_Biography[44401] = {"Vốn là một học sinh trung học bình thường, thành tích không tốt, còn thường đi muộn. Ngày nọ, gặp một con mèo nhỏ biết nói, nhận năng lực chiến binh thủy thủ","Nữ","Chưa rõ","Azabu Juban",{{8002,40}}}
TAB_Biography[44403] = {"Thiên sứ là những đứa trẻ đặc biệt thân thiết với thần, ngước nhìn, yêu thương, khen ngợi thần ở thiên đường. Một số thiên sứ mang ý chỉ của thần xuống cho loài người","Nữ","Chưa rõ","Thiên Đường",{{8002,40}}}
TAB_Biography[44506] = {"Do điều ước 'Mong được mãi bên nhau' của sinh viên được đồng ý thế là ở lại trần gian và bắt đầu sống chung","Nữ","Holy Bell","Thiên Đường",{{8002,50}}}
TAB_Biography[44507] = {"Cứ cách cả trăm năm, khi thế gian bị tà ác che phủ, truyền thế Athena xuống nhân gian. Khí chất cao quý và mỹ lệ. Tuy là nữ thần điều khiển chiến tranh, nhưng không vì sở thích cá nhân mà khởi chiến, tham gia chiến tranh đều vì bảo vệ loài người","Nữ","Quyền Trượng Nữ Thần","Hy Lạp cổ đại",{{8002,50}}}
TAB_Biography[44508] = {"Học sinh trung học bình thường, ủy viên chăm sóc sức khỏe trong lớp. Gia đình khá giả, em trai mới 3 tuổi, từ nhỏ mẹ đi làm ở ngoài với chức vụ quan trọng, bố hay ở nhà.","Nữ","Trường Cung Vàng","Phố Mitakihara",{{8002,50}}}
TAB_Biography[51301] = {"Bạo chúa tàn nhẫn. Phò tá là ma vương kiêu ngạo, vốn đảm nhiệm thủ hộ thiên chiếu, vì nguyên nhân nào đó có được {Ý chí} bản thân, dẫn dắt loài người phát hiện Nguyên Hung {Thiên chiếu}, nhân loại tiếp xúc với trùm cấm kỵ.","Nam","Chưa rõ","Quận Neon",{{8002,30}}}
TAB_Biography[51502] = {"Người ngoài hành tinh đến từ hành tinh Vegeta, lúc nhỏ lấy thân phận 'Chiến binh hạ cấp' xuống trái đất, được Võ đạo gia nuôi dưỡng, vì mất khống chế biến thành khỉ khổng lồ đạp sư phụ mất mạng rồi một mình sống trong rừng sâu. Songoku mê võ, đối thủ mạnh nào xuất hiện đều rất hưng phấn","Nam","Gậy Như Ý","Vegeta",{{8002,50}}}
TAB_Biography[51507] = {"Hades là con trai của vua Thần tộc Titans - Kronos và Rhea, là vua Minh giới, chưa từng yêu, hành sự vô tình, thích bóng tối, thích một mình, nhưng công chính vô tư. Y tạo ra thế giới sau khi mất, tức làm con người hiểu rõ tích lũy nghiệp ác mất đi phải xuống địa ngục, chịu vạn kiếp không hồi sinh, bị đày đọa vô cùng.","Nam","Kiếm Hades","Hy Lạp cổ đại",{{8002,50}}}
TAB_Biography[51508] = {"Beerus của vũ trụ thứ 7, ngủ say trong suốt 10 năm, lúc muốn phá hoại tinh cầu sẽ thức tỉnh. Trong thời gian thức tỉnh sẽ có một số tinh cầu gặp họa, có khi sẽ tìm người thay thế, có sức phá hoại đáng kinh ngạc.","Nam","Trái tim phá hoại","Vũ trụ thứ 7",{{8002,50}}}
TAB_Biography[51509] = {"Con đầu của Đấu Nha Vương Khuyển đại tướng-người thống trị Tây Quốc, người kế tục Tây Quốc, có một em trai cùng cha khác mẹ","Nam","Thiên Sinh Nha","Cổ Nghê Hồng",{{8002,50}}}
TAB_Biography[52403] = {"Một chấp sự, cũng là một ác ma. Được triệu hồi ra trong nghi thức BlackMass để định khế ước với chủ nhân. Sau khi hoàn thành khế ước được nhận linh hồn chủ nhân, trả giá là trước khi chủ nhân phục thù xong làm chấp sự và nghe lệnh chủ nhân, là lưỡi đao phục thù và bảo vệ chủ  nhân.","Nam","Chưa rõ","Địa Ngục",{{8002,40}}}
TAB_Biography[52404] = {"Bạn học trường tư thục của Gintoki và Katsura, thường đấu kiếm với Gintoki. Lúc thiên nhân xâm phạm đã ra chiến trường và kết bạn với Sakamoto. Sau khi bại trận thì mắt trái bị mù. Sau này Takasugi xây lại Kiheitai, trở thành thành phần cấp tiến, muốn phá bỏ thế giới mục nát, được xem là 'Nam nhân quá khích, nguy hiểm nhất trong lãng sĩ'","Nam","Chưa rõ","Quận Neon",{{8002,40}}}
TAB_Biography[52501] = {"'Meliodas' - Đội trưởng 'Đội kỵ sĩ Thất Đại Tội' - Đội kỵ sĩ Vương quốc, cũng là chủ quán rượu 'Boar Hat'. Thực tế là con của Ma Thần Vương, từng dẫn dắt 'Thập giới'. Vì lời nguyền của thần tối cao nên không thể phát triển, chỉ duy trì hình dạng đứa trẻ. Đồng thời nhận danh phận bất tử.","Nam","Thường Ám Quan","Ác Thần Giới",{{8002,50}}}
TAB_Biography[52510] = {"Vạn năm trước Beerus Thi Hóa đã đưa năng lượng đen vào cơ thể Dạ Xoa Vương, khiến Kuroki Gai chuyển sinh giới Thiên Không xong thì tính cách xáo trộn, muốn diệt Shurato Hidaka, cuối cùng lại bị hại dưới kiếm Shurato Hidaka.","Nam","Kiếm","Khu Đại Điền",{{8002,50}}}
TAB_Biography[53402] = {"Nam tử lạc lối giữa đúng sai tà chính, hiện rõ khát khao ham muốn, nước da trắng tuyết và trang phục lộng lẫy càng tôn lên phẩm chất cao quý, tuy nói muốn tạo thế giới mới nhưng lại nhận Amakusa Shirou chỉ để thỏa mãn khát vọng riêng, người xưng 'Giải phóng linh hồn' nhưng lại sát hại những người cầu được Thần Minh giải thoát","Nam","Chưa rõ","Quận Neon",{{8002,40}}}
TAB_Biography[53505] = {"Dưới sự trừng phạt của Ác Ma, mục đích duy nhất mà Arthas Menethil ra đời chính là chỉ huy đội quân Vong Linh to lớn","Nam","Frostmourne","Lordaeron",{{8002,50}}}
TAB_Biography[54401] = {"Vốn là sinh viên bình thường, sau khi cuốn vào 'sự việc khối sắt rơi xuống', được bác sĩ Kanou phẫu thuật và trở thành bán Ghoul có nửa huyết thống loài người","Nam","Chưa rõ","Đông Kinh",{{8002,40}}}
TAB_Biography[54506] = {"Để bảo vệ hạnh phúc của Kaname Madoka, cô đã lấy đi một số Quả Cầu Liên Hoàn, vì tình yêu dành cho Kaname Madoka vượt qua cả tuyệt vọng và hy vọng nên đã hóa thành ác ma phản bộ thế giới","Nữ","Ngọc Hắc Ám","Phố Mitakihara",{{8002,50}}}
TAB_Biography[52511] = {"Hội trưởng Guild 'Ainz Ooal Gown', sống tại tầng 9 Đại Lăng Tẩm Nazarick, người đứng đầu trong 41 đấng tối cao của các NPC Nazarick. Bên ngoài là một bộ xương mạnh mẽ nhưng có nội tâm giống con người","Nam","Quyền Trượng Hermes","Nazarick",{{8002,50}}}
TAB_Biography[41511] = {"17 tuổi khởi hành từ quê nhà, đến 19 tuổi bị thiêu sống nên tên bà đã được ghi vào lịch sử, bà là thánh nữ đã bảo trợ nước Pháp, sau khi đẩy lùi được cuộc tiến công bà bị mưu hại và chịu kết cục bi thảm.","Nữ","Thánh nữ Hồng Liên","Orleans",{{8002,50}}}
TAB_Biography[51512] = {"Rimuru trong tình huống bất đắc dĩ triệu hồi Nhất Trụ trong Ác Ma, còn Nhị Trụ chỉ là tay sai tự gọi ra của nó. Mạnh vô cùng, trung thành với Rimuru, không cho người khác thất kính","Nam","Chưa rõ","Thất Trụ Nguyên Sơ",{{8002,50}}}
TAB_Biography[52513] = {"Được xem là tồn tại của Orochi, từ khi tạo ra thế giới luôn bảo vệ loài người, nhưng từ khi loài người tách khỏi tự nhiên, với loài người mà nói “Orochi” là tượng trưng của cái “ác”","Nam","Phù Hiệu Bóng Tối","Trái Đất",{{8002,50}}}
TAB_Biography[31510] = {"Một trong 7 sát thủ Tinh Anh Đế Quốc, thủ lĩnh của {Night Raid}, được gọi là “Sát Thủ Hàng Đầu”, tính tình điềm đạm, xem trọng đồng đội, ít khi bộc lộ tiếng lòng, mà thường hành động cảm tính.","Nữ","Thôn Vũ","Đế Đô",{{8002,50}}}
TAB_Biography[41512] = {"Trong thần thoại Mesopotamia, Ishtar lao vào Núi Ebih, cứ đi một bước sẽ tăng thần uy, cuối cùng chinh phục được đỉnh núi, dùng giáo đâm xuyên lòng đất, khiến ngọn núi này sụp đổ.","Nữ","Thuyền Thiên Giới Maanna","Mesopotamia",{{8002,50}}}
TAB_Biography[54514] = {"Một cô gái bí ẩn và xinh đẹp. Với chất giọng thiên phú, là một ca sĩ thần tượng trực tuyến và là thành viên của Nhà Tang Lễ. Cô có tài thiện xạ, huyết dịch và giọng ca có thể trấn áp bệnh hư ảo, nhưng cô không giỏi nấu nướng.","Nữ","Glock 17","S11",{{8002,50}}}
TAB_Biography[43513] = {"Thần mạnh nhất trong thần thoại Bắc Âu, từng một mình đẩy lùi cuộc tấn công của Cự Nhân Băng Giá, được gọi là 'Berserker Sấm', cầm một thần khí khổng lồ-Búa 'Mjolnir'.","Nam","Búa Mjolnir","Bắc Âu",{{8002,50}}}
TAB_Biography[22516] = {"Vị tướng trẻ nhất và mạnh nhất đế quốc, cũng là thủ lĩnh của tổ chức 'Thợ săn'. Nắm giữ năng lực băng mạnh mẽ, tin tưởng 'cá lớn nuốt cá bé, kẻ mạnh tồn tại'. Nhưng cũng rất dịu dàng với thuộc hạ và người yêu.","Nữ","Ác Ma Thuần Túy","Biên giới phía bắc đế quốc",{{8002,50}}}
TAB_Biography[63501] = {"Vốn sống ở trái đất, bất ngờ qua đời, chuyển sinh đến thế giới khác trở thành Slime. Có 3 kỹ năng độc đáo - 'Kẻ Săn Mồi', 'Đại Hiền Giả' và 'Kẻ Biến Chất'. Hiện là thủ lĩnh của 'Liên Bang Ma Quốc', đã tiến hóa thành 'Ma Vương Thức Tỉnh', là 'Thánh Ma Hỗn Thế Hoàng' của 'Bát Tinh Ma Vương'","Không","Đại Hiền Giả","Rừng Đại Ngàn Jura",{{8002,50}}}
TAB_Biography[51515] = {"Chiến binh Hỏa Diệm Tím có năng lực thao tác, hậu duệ Bát Thần bảo vệ một trong ba thần khí -'Yasakanino Magatama'; Vì 'Khế Ước Đỏ' giữa gia tộc và tộc Orochi khiến trong người có dòng máu Orochi và sinh ra một dạng 'Bạo tẩu đỏ' không nhận thức, biến thành 'Orochi Iori'","Nam","Thương Viêm","Quận Neon",{{8002,50}}}
TAB_Biography[31517] = {"Học viên có tinh thần phản xạ xuất chúng và năng lực nhìn thấu suốt mới được Heathcliff đánh giá đẳng cấp mạnh nhất. Từng tham gia đợt Test SAO giới hạn 1000 người, trong thời gian test vô cùng tập trung. Vì hoàn toàn chìm trong SAO bản chính thức mà dính líu đến việc game khai tử, từ đó bắt đầu liên quan các sự việc thế giới ảo. ","Nam","Elucidator; Dark Repulsor","Saitama Prefecture",{{8002,50}}}
TAB_Biography[41514] = {"Một tinh linh ra mắt lần đầu-Tinh Linh Kiếm. Là một thiếu nữ tinh linh trước khi hiện thân là Shido, có mái tóc màu màn đêm, dài xuống đầu gối, đôi mắt sắc thủy tinh. Cá tính đơn thuần đáng yêu, sức ăn đáng kinh ngạc, vô cùng tò mò với mọi sự vật.","Nữ","Sandalphon","Tengu",{{8002,50}}}
TAB_Biography[53516] = {"Ninja thiên tài của tộc Uchiha làng Ninja Konoha Hỏa Quốc, người chuyển thế luân xa của con trưởng Lục Đại Tiên Nhân - Indra. Thời niên thiếu vì thấy tộc Uchiha bị anh trai Uchiha Itachi tiêu diệt, từ đó bước lên con đường báo thù.","Nam","Kiếm Kusanagi","Làng Lá",{{8002,50}}}
TAB_Biography[64502] = {"Cây thần hóa thành thực thể Thập Vĩ, thần sáng thế của thế giới Ninja, tổ tiên Chakra, có năng lực Byakugan và Rinne Sharingan. Ăn quả thần nhận năng lượng lớn mạnh và hợp nhất với cây thần, bình định phân tranh của người trái đất, giúp Kaguya có được địa vị cao, được gọi là 'Nữ Thần Thỏ'.","Nữ","Zetsu Đen","Hành Tinh Khác",{{8002,50}}}
TAB_Biography[42515] = {"Hoàng tử thứ 11 của Holy Britannian Empire, phó hội trưởng hội học sinh Học viện Ashford, người lãnh đạo đoàn kỵ sĩ Đen-zero, hoàng đế thứ 99 Holy Britannian Empire. Trong một lần bất ngờ nhận được Sức Mạnh Geass C.C. trao cho, thề phải làm tan nát Holy Britannian Empire, cuối cùng ra quyết định và tiến hành kế hoạch 'Continued Story'. ","Nam","Cao Văn","Britannia",{{8002,50}}}
TAB_Biography[52517] = {"Pháp Sư Đặc Cấp, ra đời trong gia tộc Gojo có thuật thức Vô Hạ Hạn, vì sinh ra để có thuật thức {Lục Nhãn} nên có thể nắm chắc thông thạo. Nam nhân ngoài tính cách ra, cái gì cũng 'hoàn mỹ'. Tính tùy tiện, ghét 'chính luận'. Hiện tại là kẻ mạnh nhất trong các nhân vật ra mắt.","Nam","Bịt Mắt","Nhật Bản",{{8002,50}}}
TAB_Biography[61503] = {"Vua Quincy, người sáng lập và là hoàng đế đế quốc Vô Hình, tổ tiên của mọi Quincy; chữ Thánh là 'A', tượng trưng cho năng lực 'toàn trí toàn năng'. Bạo ngược, máu lạnh và thận trọng, lợi dụng những ai có thể lợi dụng, khi mất đi giá trị lợi dụng sẽ trảm  sát không thương tiếc.","Nam","Reishi Sword","Đế quốc Vô Hình",{{8002,50}}}
TAB_Biography[44516] = {"Tính cách đơn thuần dịu dàng, tự nhiên lại khó hiểu, luôn có tư duy kỳ lạ, một cô gái yêu thích hòa bình, luôn mang đến tiếng cười và sự thoải mái. Có nhận thức tâm linh nhạy bén và kỹ năng kiểm soát Reiatsu tinh tế, năng lực 'Shun Shun Rikka' trong kẹp tóc trên đầu.","Nữ","Shun Shun Rikka","Trấn Karakura",{{8002,50}}}
TAB_Biography[54518] = {"Sau hơn cả trăm năm giờ mới tỉnh giấc - Ma Nữ Tóc Đen. Có thể dùng ma lực lớn mạnh vô cùng, luôn đi săn các sứ giả từ thế giới tự nhiên - thiên sứ. Dùng hai cây súng trang bị ở tứ chi để chiến đấu. Đã ký khế ước với ma thú lớn mạnh, có thể đưa chúng từ địa ngục lên diệt thiên sứ.","Nữ","Scarborough Fair","Vigrid",{{8002,50}}}
TAB_Biography[43517] = {"Người lái EVA 02, người đủ điều kiện thứ 2 NERV. Là một thần đồng, học vị đại học lúc thanh thiếu niên. Tính cách nóng nảy và màu ấn tượng đỏ rực cũng là đặc trưng của cô ấy, hơn nữa cảm thấy khá tự hào khi bản thân là người lái EVA. Thường sôi nổi và ảnh hưởng mạnh đến không gian của người khác, đặc biệt là Ikari Shinji. Yêu cầu mãnh liệt khiến bản thân cảm thấy kiêu ngạo, còn rất tệ trong xử lý thất bại của bản thân. ","Nữ","Thương Cassius","Nước Đức",{{8002,50}}}
TAB_Biography[62504] = {"Tàn nhẫn vô tình nhưng lại có mê lực nhân cách độc đáo để ác nhân đều bái phục hắn, được gọi là 'Cứu thế ác nhân'. Kẻ thù cũ của tộc Joestar, một trong những nhân vật nòng cốt. Vẻ ngoài xinh đẹp, có chút không giống nam nhân, lời nói ngọt ngào.","Nam","the world","Luân Đôn",{{8002,50}}}
TAB_Biography[51519] = {"Thiếu niên vừa lộ diện đã bị tu nữ cự tuyệt lời cầu hôn, nhưng vẫn không từ bỏ kiên quyết muốn lấy tu nữ. Là bạn tốt, lại là đối thủ của Yuno, hai người từng giao hẹn xem ai trở thành Ma Pháp Vương. Vì thường xuyên tu luyện nên có một cơ thể săn chắc, thị lực và phản ứng cũng xuất chúng. Ngẫu nhiên nhận được Sách ma đạo Black Clover, Phản Ma Pháp có ác ma trú ngụ trong sách.","Nam","Kiếm Chém Ma","Làng Hage",{{8002,50}}}
TAB_Biography[41518] = {"Luffy với biệt hiệu 'Mũ Rơm', cháu của anh hùng hải quân Monkey D Garp, con trai thủ lĩnh quân cách mạng Monkey·D·Dragon. Người có năng lực Quả Cao Su, vì ăn nhầm Quả Cao Su nên bản thân nhận có thể co duỗi như cao su. Mơ ước tìm được One Piece trong truyền thuyết, trở thành Vua Hải Tặc.","Nam","Mũ Rơm","Đông Hải",{{8002,50}}}
